    { q: 'Which Act implemented Law Commission work to codify sentencing law?', o: ['Sentencing Act 2020', 'Criminal Justice Act 1967', 'Theft Act 1968', 'Legal Aid Act 1988'], x: 'The Sentencing Code.' },
    { q: 'The Criminal Cases Review Commission was recommended by…', o: ['the Runciman Royal Commission', 'the Law Commission', 'the Macpherson Inquiry', 'the Leveson Inquiry'], x: 'Criminal Appeal Act 1995.' }
